function assessCompany(company,scope,now){
 const review=institutionProfiles.get(company);
 if(review&&scope){
  const market=reviewedScope(review,'market_profiles',scope,now);
  const source=market&&researchSources.get(market.source_ids[0]);
  const pending=market?.evidence_watch?.state==='changed_needs_review';
  const grade=pending?1:market?.grade??(review.grade?1:0);
  return {...review,grade,label:companyValueLabels[grade],asOf:market?.checked_at,
   selection:review.selection==='backup'?'backup':pending||!market?'hold':review.selection,
   reason:pending?'该招聘市场的关键来源有变动，等待核实原文':
    market?.reason||'已核对机构主体。该履历在本岗位对应招聘市场的认可度仍待补证',
   markets:market?[market.market]:[],marketKey:market?.market_key,url:source?.url,kind:source?.title,checked:Boolean(source),
   limit:market?.limit||'核验法定雇主、主要业务和目标招聘方对相关经历的要求',
   evidence_watch:market?.evidence_watch,proofs:market?.source_ids||[]};
 }
  if(review)return {...review,label:companyValueLabels[review.grade],
   selection:review.evidence_watch?.state==='changed_needs_review'?'hold':review.selection||'hold'};
 const facts=institutionEvidence.filter(e=>e.company===company&&!e.metric);
 return {company,grade:facts.length?1:0,label:companyValueLabels[facts.length?1:0],markets:[],
  reason:facts.length?'已有机构业务出处，但尚无足够证据判断在目标招聘市场的认可度。':'公司主体或招聘市场认可度尚未独立核验。',
  limit:'待核验不等于差公司；也不能只因岗位方向对口、名字像大机构或标题写了投资，就进入首推。',
  url:facts[0]?.url,asOf:facts[0]?.asOf,checked:facts[0]?.checked,kind:facts[0]?'业务来源，非认可度证明':'待核',judgment:false};
}
function companyEvidence(a){
 const v=a.companyValue,box=el('div','company-evidence');
 box.append(el('p','',v.reason),el('p','muted','适用招聘市场：'+(v.markets.join('、')||'待核验')));
 if(v.proofs?.length)for(const id of v.proofs)box.append(researchSource(id));
 else if(v.url)box.append(link(v.kind+' · '+(v.checked?'核验 ':'')+v.asOf,v.url));
 box.append(el('p','muted',v.limit));const compare=el('button','','比较这家机构');compare.onclick=()=>openInstitutionResearch(a.company);box.append(compare);
 return box;
}
